def second_largest(nums):
    if not nums:
        return None

    # Get unique numbers and sort them in descending order
    unique_nums = sorted(list(set(nums)), reverse=True)

    # Check if there are at least two distinct numbers
    if len(unique_nums) < 2:
        return None
    else:
        # The second largest distinct number is at index 1
        return unique_nums[1]

